class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        # Create a set of prefixes for quick lookup
        prefix_set = set()
        for word in words:
            for i in range(1, len(word) + 1):
                prefix_set.add(word[:i])

        @lru_cache(None)
        def dp(i):
            if i == len(target):
                return 0
